// Embedded price table, generated by scripts/update-prices.ts. A subpath export
// (`@burn-watch/shared/prices`), not part of the index, so code that never
// prices anything does not bundle it.
import table from './prices.json' with { type: 'json' }
import { PriceTableSchema } from './schemas.js'

export const PRICE_TABLE = PriceTableSchema.parse(table)
